// TEMPLATE-E2E TR-11 (J434): Mossgate Hollow's own build (scene source plus its gameplay rows) as a native fixture,
// in place of the retired Template's. Every generated byte comes from the build itself.
import { builtSceneShardfile } from '../../src/sharddev/scene/shardfile';
import { compileScript } from '../../src/sharddev/bake/compileScript';
import { lowerMaterialGraphs } from '../../src/sharddev/materialGraphFiles';
import { gameplay } from '../../src/shards/mossgate/generators/gameplay';
import { mossgate } from '../../src/shards/mossgate/generators/shard';

const scene = await builtSceneShardfile(mossgate.describe(), compileScript, { extend: gameplay });
// D74, as the build does: inline material graphs (MZ7's fire) become graph files before any admission reads them
const lowered = lowerMaterialGraphs(scene.shard);
const built = { shard: lowered.declaration as typeof scene.shard, assets: new Map([...scene.assets, ...lowered.assets]) };
/** Native tests consume the same rows and bytes as the executable build entry. */
export const MOSSGATE_SOURCE = built.shard;
/** Preserve independently owned input bytes for each admission. */
export function mossgateAssets(hashes?: ReadonlySet<string>): Map<string, Uint8Array> {
  const selected = hashes === undefined ? [...built.assets.keys()] : [...hashes];
  return new Map(selected.map(hash => {
    const bytes = built.assets.get(hash);
    if (bytes === undefined) throw new Error('Unknown Mossgate fixture asset');
    return [hash, Uint8Array.from(bytes)];
  }));
}
